/* ---------- scene 3: two-pan balance, "Total assets" vs "Total Liabilities + Equity" ---------- */

const PAN_DROP = 340;
const BEAM_HALF = 250;
const Scales: React.FC<{leftT: (k: number) => number; rightT: (k: number) => number}> = ({leftT, rightT}) => {
  const widths = [176, 136, 96, 56];
  const leftC = [BLUE, BLUE_LIGHT, BLUE, BLUE_LIGHT];
  const rightC = [ORANGE, '#FFB257', TEAL, '#5FC3CC'];
  const bh = 52;
  const gp = 6;
  const px = 460; // pivot x in svg coordinates (svg left = 80)
  const py = 90;
  const lc = [0, 1, 2, 3].reduce((a, k) => a + leftT(k), 0);
  const rc = [0, 1, 2, 3].reduce((a, k) => a + rightT(k), 0);
  const th = ((lc - rc) * 1.9 * Math.PI) / 180; // heavier side dips; level once both stacks are built
  // left end goes down when th>0
  const L = {x: px - BEAM_HALF * Math.cos(th), y: py + BEAM_HALF * Math.sin(th)};
  const R = {x: px + BEAM_HALF * Math.cos(th), y: py - BEAM_HALF * Math.sin(th)};
  const pan = (E: {x: number; y: number}, widthsArr: number[], colors: string[], t: (k: number) => number) => {
    const y = E.y + PAN_DROP;
    return (
      <g>
        <line x1={E.x} y1={E.y} x2={E.x - 120} y2={y} stroke="#44506A" strokeWidth="4" strokeLinecap="round" />
        <line x1={E.x} y1={E.y} x2={E.x + 120} y2={y} stroke="#44506A" strokeWidth="4" strokeLinecap="round" />
        {widthsArr.map((wd, k) => {
          const tk = t(k);
          const by = y - (k + 1) * (bh + gp) + gp;
          return <rect key={k} x={E.x - wd / 2} y={by - (1 - tk) * 40} width={wd} height={bh} rx="14" fill={colors[k]} opacity={tk} />;
        })}
        <rect x={E.x - 128} y={y} width="256" height="24" rx="12" fill={BLUE} />
        <circle cx={E.x} cy={E.y} r="9" fill="#44506A" />
      </g>
    );
  };
  return (
    <svg width="840" height="540" viewBox="0 0 840 540" style={{position: 'absolute', left: 80, top: 330, overflow: 'visible'}}>
      <path d="M360 478 H560 L530 446 H390 Z" fill="#C9DCF6" stroke="#9FBFEA" strokeWidth="3" strokeLinejoin="round" />
      <rect x={px - 13} y={py} width="26" height="360" rx="8" fill="#C9DCF6" stroke="#9FBFEA" strokeWidth="3" />
      {pan(L, widths, leftC, leftT)}
      {pan(R, widths, rightC, rightT)}
      <line x1={L.x} y1={L.y} x2={R.x} y2={R.y} stroke={BLUE} strokeWidth="18" strokeLinecap="round" />
      <circle cx={px} cy={py} r="24" fill={ORANGE} stroke="#FFFFFF" strokeWidth="5" />
    </svg>
  );
};

